namespace elit21::shopify::webhooks {CustomerWebhookHandler::CustomerWebhookHandler():platform::BusinessComponent("CustomerWebhookHandler","Persistent Shopify webhook domain handler",platform::BusinessComponentSpec{"shopify","handle_webhook",{},true,false,16U*1024U*1024U}){}CustomerWebhookHandler::CustomerWebhookHandler(Database&database):CustomerWebhookHandler(){database_=&database;}Result<void>CustomerWebhookHandler::handle(const ShopifyWebhook&event){if(!database_)return Result<void>::failure("CustomerWebhookHandler is not bound to Database");return persistWebhookTask(*database_,event,{ShopifyWebhookTopic::customers_data_request,ShopifyWebhookTopic::customers_redact});}platform::OperationResult CustomerWebhookHandler::execute(const platform::OperationContext&context){auto r=executeBusiness(context);r.metrics["database_bound"]=database_?1.0:0.0;r.attributes["handler"]="CustomerWebhookHandler";return r;}}
